import { API_URL } from '../../config.js';
import type { ImageScope } from '@motivation/shared';
import { ImageUploadError, isPermanentRefusal, uploadImageMultipart } from '../files.service.js';
import {
    IMAGE_UPLOAD_DRAIN_LOCK,
    getQueueLocks,
    withQueueDrainLock,
    type LocksApi,
} from './queue-drain-lock.js';
import {
    IMAGE_UPLOAD_SYNC_TAG,
    deleteUpload,
    getPendingUploads,
    getUploadedRecords,
    markRejected,
    markUploaded,
    type ImageUploadQueueEntry,
} from './image-upload-store.js';

/**
 * Drains the image upload queue. Each pending entry is POSTed to
 * /api/files/images (multipart) and, on success, marked uploaded with the
 * server-assigned image_path. Story 124.
 *
 * The POST itself goes through `files.service.ts`'s `uploadImageMultipart`
 * (story 264) — the hand-rolled copy that used to live here forgot the
 * `X-Manual-AbortSignal` opt-out, so the service worker aborted slow uploads at
 * 15 s and the offline proxy reported the multipart body as a JSON-parse 503.
 *
 * Story 362: the drain then puts the path on its food or meal itself (a PATCH
 * by `local_ref`) and drops the entry only once that lands. Before, the path
 * reached its row only through app.ts's BroadcastChannel listener — with no
 * window open, the photo was uploaded and lost. A row the server does not have
 * yet (made offline, still syncing) keeps the entry uploaded; the next drain
 * re-sends only the PATCH. A permanent refusal (4xx but 408/429) is set aside
 * with the server's words and the queue carries on.
 *
 * On a transient error the entry is left in place — the next Background Sync
 * fire (or a manual retry) tries again. Throws so the SW's `event.waitUntil`
 * reports the failure to the browser, which will re-fire `sync` once
 * connectivity returns.
 */

export const IMAGE_UPLOAD_SUCCESS_CHANNEL = 'motivation-image-uploads';

export interface ImageUploadSuccessMessage {
    type: 'image-upload-success';
    queue_id: string;
    image_path: string;
    scope?: string;
    local_ref?: string;
}

export interface ShippingDeps {
    fetch?: typeof fetch;
    apiUrl?: string;
    now?: () => string;
    /** Override the broadcast channel for tests; default opens IMAGE_UPLOAD_SUCCESS_CHANNEL. */
    broadcast?: (message: ImageUploadSuccessMessage) => void;
    /** Override the Web Locks API used for cross-realm serialization (tests). */
    locks?: LocksApi;
}

export interface ShippingResult {
    /** Delivered: on their row (or needing none) and dropped from the queue. */
    uploaded: number;
    failed: number;
    /** Refused for good this drain; kept for the status screen. */
    rejected: number;
    /** Uploaded, but their row is not on the server yet. */
    waiting: number;
}

/** Where a scope's photo lives; `ai` photos travel inside their estimate instead. */
const ROW_ROUTES: Partial<Record<ImageScope, string>> = {
    food: 'food-items',
    meal: 'meals',
};

/** A photo whose row is still missing after this long is set aside — the row was most likely deleted. */
const ROW_WAIT_HOURS = 7 * 24;

/**
 * Story 264: this queue is drained from app.ts's `online` handler AND the service
 * worker's Background Sync handler — two realms with no shared state, so nothing
 * stopped both from reading the same pending row and uploading its bytes. The
 * cross-realm lock makes read → upload → mark → delete mutually exclusive; the
 * second drain then finds an empty queue.
 */
export async function shipPendingImageUploads(deps: ShippingDeps = {}): Promise<ShippingResult> {
    return withQueueDrainLock(
        deps.locks ?? getQueueLocks(),
        IMAGE_UPLOAD_DRAIN_LOCK,
        () => drainOnce(deps),
    );
}

async function drainOnce(deps: ShippingDeps): Promise<ShippingResult> {
    const fetchImpl = deps.fetch ?? fetch.bind(globalThis);
    const apiBase = deps.apiUrl ?? API_URL;
    const now = deps.now ?? (() => Temporal.Now.instant().toString());
    const broadcast = deps.broadcast ?? defaultBroadcast;

    const result: ShippingResult = { uploaded: 0, failed: 0, rejected: 0, waiting: 0 };

    const setAside = async (entry: ImageUploadQueueEntry, reason: string): Promise<void> => {
        console.error(`[image-upload] ${entry.scope} photo ${entry.filename} set aside: ${reason}`);
        await markRejected(entry.id, reason, now());
        result.rejected += 1;
    };

    const deliver = async (entry: ImageUploadQueueEntry, imagePath: string, uploadedAt: string): Promise<void> => {
        const outcome = await putOnRow(entry, imagePath, fetchImpl, apiBase);
        if (outcome.kind === 'refused') {
            await setAside(entry, outcome.reason);
        } else if (outcome.kind === 'no-row') {
            const deadline = Temporal.Instant.from(uploadedAt).add({ hours: ROW_WAIT_HOURS });
            if (Temporal.Instant.compare(Temporal.Instant.from(now()), deadline) > 0) {
                await setAside(entry, `Uploaded, but its ${entry.scope} never reached the server in ${ROW_WAIT_HOURS / 24} days — it was probably deleted.`);
            } else {
                result.waiting += 1;
            }
        } else {
            await deleteUpload(entry.id);
            result.uploaded += 1;
        }
    };

    // Offline, 5xx, 408/429 throw out of here: the entry stays where it is, the
    // rest re-surface on the next sync wake-up, and the SW's `event.waitUntil`
    // sees the error, so the browser retries `sync`.

    // Uploaded on an earlier drain, but their row was not on the server yet: only the PATCH is left.
    for (const entry of await getUploadedRecords()) {
        await deliver(entry, entry.image_path, entry.uploaded_at);
    }

    while (true) {
        const batch = await getPendingUploads(25);
        if (batch.length === 0) break;

        for (const entry of batch) {
            let imagePath: string;
            try {
                imagePath = await uploadOne(entry, fetchImpl, apiBase);
            } catch (err) {
                if (!(err instanceof ImageUploadError && isPermanentRefusal(err.status))) throw err;
                await setAside(entry, `The server refused this photo (${err.status}): ${err.message}`);
                continue;
            }
            const uploadedAt = now();
            await markUploaded(entry.id, imagePath, uploadedAt);
            // An open window adopts the path into its form and its local replica straight away.
            broadcast({
                type: 'image-upload-success',
                queue_id: entry.id,
                image_path: imagePath,
                scope: entry.scope,
                local_ref: entry.local_ref,
            });
            await deliver(entry, imagePath, uploadedAt);
        }
    }

    if (result.waiting > 0) {
        throw new Error(`${result.waiting} uploaded photo(s) wait for their row to reach the server`);
    }
    return result;
}

async function uploadOne(entry: ImageUploadQueueEntry, fetchImpl: typeof fetch, apiBase: string): Promise<string> {
    const { image_path } = await uploadImageMultipart(entry.scope, entry.blob, entry.filename || 'image', { fetchImpl, apiBase });
    return image_path;
}

type RowOutcome = { kind: 'done' } | { kind: 'no-row' } | { kind: 'refused'; reason: string };

/** PATCH the uploaded path onto the food or meal it was taken for. Idempotent, so a retry is safe. */
async function putOnRow(entry: ImageUploadQueueEntry, imagePath: string, fetchImpl: typeof fetch, apiBase: string): Promise<RowOutcome> {
    const route = ROW_ROUTES[entry.scope];
    if (!route || !entry.local_ref) return { kind: 'done' };

    const response = await fetchImpl(`${apiBase}/api/sections/health/${route}/${encodeURIComponent(entry.local_ref)}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ image_path: imagePath }),
    });
    if (response.ok) return { kind: 'done' };
    if (response.status === 404) return { kind: 'no-row' };

    const body = await response.json().catch(() => null) as { error?: string } | null;
    const detail = body?.error ?? response.statusText;
    if (isPermanentRefusal(response.status)) {
        return { kind: 'refused', reason: `Uploaded, but the server would not put it on its ${entry.scope} (${response.status}): ${detail}` };
    }
    throw new Error(`Putting an uploaded photo on its ${entry.scope} failed (${response.status}): ${detail}`);
}

function defaultBroadcast(message: ImageUploadSuccessMessage): void {
    if (typeof BroadcastChannel === 'undefined') return;
    const ch = new BroadcastChannel(IMAGE_UPLOAD_SUCCESS_CHANNEL);
    try {
        ch.postMessage(message);
    } finally {
        ch.close();
    }
}

/**
 * Registers the Background Sync tag. Called by the main thread after
 * enqueuing an upload offline (or after a flaky online upload failed). Throws
 * if Background Sync is unavailable — the app is Chrome-only with secure-
 * origin flags, so we Fail Loud per development_principles.md.
 */
export async function requestImageUploadSync(): Promise<void> {
    if (typeof navigator === 'undefined' || !navigator.serviceWorker) {
        throw new Error('Service Worker is not available — image uploads cannot ship');
    }
    const registration = await navigator.serviceWorker.ready;
    if (!registration.sync) {
        throw new Error('Background Sync API is not available — image uploads cannot ship');
    }
    await registration.sync.register(IMAGE_UPLOAD_SYNC_TAG);
}
